-- GENERATED by `wfj generate` from data/gossip/gossip-67.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["6703f20be7ca5c1c"] = { "Ciao ciao, <piccolo/piccola> {race}. Raze andare ora.", "." },
  ["67073178acd43cf7"] = { "Puoi imparare a cucire a Orgrimmar. È a nord. Forse uno degli Orgrimmar Grunt può aiutarti.", "." },
  ["6715a9b2defc035b"] = { "Per ragioni che non riesco a capire, l'anziano Thunderhorn è andato all'Anfratto Brulicante, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "." },
  ["672b5ffabf3673c9"] = { "{class}, l'⟦Horde=Orda⟧ ha raccolto tutto ciò che le serve per la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧! Ora aspettiamo che quella misera ⟦Alliance=Alleanza⟧ ci raggiunga. Quando lo farà, cominceremo a trasportare tutto a ⟦Silithus=Silitus⟧. Una volta completati i preparativi laggiù, non dovrebbe passare molto prima che la guerra cominci!", "." },
  ["672e08d2ac0f85b3"] = { "Ben fatto. Un duro colpo per Arugal, non c'è dubbio!", "." },
  ["67318b4829532a33"] = { "Se non fosse per la loro incredibile, stupida fortuna, i goblin si schianterebbero con l'auto a ogni gara!", "." },
  ["6731ee44b682228a"] = { "Dov'è l'anziano Darkhorn?", "." },
  ["6734c58905bf7e21"] = { "Ehilà, <amico/amica>. Tu sei nel posto giusto pe' imparare a usare 'na nuova arma.", "." },
  ["67378d5e76ae5a67"] = { "<Benvenuto/Benvenuta> a ⟦Ironforge=Forgiardente⟧, {class}.", "." },
  ["673b6b97de8e7746"] = { "Se non fosse per il Torvo Beone, passerei il tempo libero a strappare le ali ai cuccioli di drago.", "." },
  ["674b320b31ea55c8"] = { "Eh sì, posso insegnarti a pescare.", "." },
  ["674c28acab48fc9a"] = { "Lo spirito di ⟦Stonetalon=Petrartiglio⟧ piange. Piange dalle vette dei suoi monti ai suoi fiumi, fino ai suoi alberi recisi e morenti.", "." },
  ["6753412bd0ee86c6"] = { "Vincitore! Noi avere un vincitore qui!", "." },
  ["67582c41d44e7a2e"] = { "Lame di luce!", "." },
  ["675b9231e99fc077"] = { "Se cadiamo, il ⟦Darrowshire=Borgo di Darrow⟧ è perduto!", "." },
  ["676456d8354126cd"] = { "Devi fare ciò che ritieni giusto, Marcus. Abbiamo servito insieme sotto Turalyon. È lui che ha fatto di noi gli uomini che siamo oggi. Con me ha sbagliato? Credi davvero che il mio intento sia nuocere alla nostra Alleanza? Getterei mai vergogna sui nostri eroi?", "." },
  ["6766bef0b3c92d7f"] = { "La tua ricerca è quasi conclusa. Cerca la tua verità nella sala d'ingresso della fortezza di Thrall, nella Valle della Saggezza.", "." },
  ["676b9288e828b2dd"] = { "Ti godi la festa, {class}? La mia merce può dare una marcia in più alla tua giornata. Niente di meglio di cibo caldo e qualcosa da bere!\n\nE se non l'hai ancora fatto, prendi un amico o due e festeggiate intorno al palo dei nastri: di sicuro ti tirerà su il morale!", "." },
  ["67766cde299b10c2"] = { "C'è silenzio qui....", "." },
  ["677ee69f10fece27"] = { "Salve, giovane {class}. Sono Rathiril Sunlance, magistro anziano dell'High Order qui a Zephras Isle. Fa sempre piacere vedere giovani shen'dorei dagli occhi vivaci, pronti a fare il loro dovere al servizio della loro patria.\r\n\nMa non lasciare che questo vecchio mago impolverato ti trattenga: avrai sicuramente molte avventure da affrontare. Passa pure più tardi, se vuoi parlare ancora.", "." },
  ["678276f1a290935f"] = { "Dai retta a me: non sederti vicino alle ombre.", "." },
  ["6787024e95051180"] = { "Una storia molto triste. Grazie, spirito.", "." },
  ["678956f884b37f22"] = { "Salve, {name}. Se ti serve aiuto per completare la tua missione, non hai che da chiedere. Il mio guardiano, Raze, può aiutarti a sconfiggere i Bracconieri Ombroseta. Usa questo ⟦Staff of Command=Bastone del Comando⟧ per guidare Raze in battaglia. È addestrato ad attaccare SOLO i Bracconieri Ombroseta.", "." },
  ["678ab7908a16aa8f"] = { "C'è un istruttore di Scuoiatura a Orgrimmar. Per arrivarci, prendi la strada verso nord uscendo da ⟦Razor Hill=Tranciacolle⟧. Quando arrivi, chiedi indicazioni a un ⟦Orgrimmar Grunt=Grunt di Orgrimmar⟧.", "." },
  ["6791d3a354d7dc3a"] = { "Finché quei nani restano laggiù non avremo problemi. Dove sei <diretto/diretta>, {name}?", "." },
  ["6796e8b44869700c"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ è controllato dall'⟦Horde=Orda⟧.", "." },
  ["67991ba376a17be7"] = { "Salute a te, <compagno/compagna> di noviziato dell'High Order.", "." },
  ["67a5cc2d744c669d"] = { "Wow... tu SEI ver<o/a> <re/regina>! Io mai pensato di vedere questo guanto in mia vita! Sembra che non ha più mojo... forse elfo inquietante ha provato a rovinare guanto. Be', io dico HAR HAR a lui!\n\nGuarda: questo segno su guanto è segno magico dei vecchi vecchi VECCHI tempi, più vecchio dei Gordok, dicono. Be', come Capitano dei Gordok, noi tutti impariamo una cosa più e più volte: come far tornare in vita segno e ridare potere a guanto!\n\nIo lo faccio per te, <re/regina>! Ecco, prendi guanto e regna PER SEMPRE!", "." },
  ["67a6ad68b98b3fa2"] = { "Lo stimato dottor Gustaf VanHowzen può addestrarti ancora. Lo trovi a Theramore, dove cura i feriti nella caserma.", "." },
  ["67ab468296f118b1"] = { "Oha! Fa piacere vedere chi fa il fabbro come me e non ha paura di sporcarsi le mani.\r\n\nSe cerchi lavoro, temo d'essere un po' a corto di provviste al momento. La nostra fonte di minerale più affidabile è stata invasa dai wendigo e ora la grotta è abbandonata. I minatori hanno dovuto mollare tutto quando sono scappati!\r\n\nDi', perché non vai a dare un'occhiata alla Tana Selvaggia, a ovest, e vedi se trovi qualcuna delle nostre spedizioni perdute? Ci risparmieresti un sacco di guai.", "." },
  ["67ad761c35768e50"] = { "Dov'è? Vai qui accanto, all'Arms of Legend. Lì forgia armi speciali per i grandi eroi. Rendigli onore e forse ti mostrerà come creare oggetti leggendari.", "." },
  ["67b0a681306147c8"] = { "Baristolth, ho perso il mio distintivo e me ne serve uno nuovo.", "." },
  ["67b6a8f3684be40f"] = { "Allontanati da quei barili!", "." },
  ["67bca016b2740611"] = { "%s inizia a salmodiare in una lingua antica, evocando qualcosa di natura malvagia.", "." },
  ["67c5c23f1bd436b5"] = { "In un luogo chiamato Feralas, a ovest di qui, gli ippogrifi, compagni di lunga data degli elfi della notte, sono in pericolo.\n\nHo bisogno che tu salvi un uovo dalle Rovine di Isildien, a sud, laggiù. Il Super Egg-O-Matic può analizzare qualsiasi uovo gli venga portato e stabilire se è probabile che si schiuda. Poi mando le uova ai druidi, al sicuro dalla magia oscura degli ogre Gordunni.\n\nSappi però, {name}, che alcune delle uova salvate sono marce e non si schiuderanno mai.", "." },
  ["67c7d2d159e3e6a2"] = { "Shhh... sarà tutto finito presto.", "." },
  ["67cb75b22cba2ba6"] = { "Il mio volo è pronto! Soldati, venite in mio aiuto!", "." },
  ["67cd1d720e0cc967"] = { "All'attacco! Per l'⟦Horde=Orda⟧!", "." },
  ["67d240ec86423c9e"] = { "⟦Scarlet Monastery=Monastero Scarlatto⟧", "." },
  ["67df304efa945fb8"] = { "Proteggete il caposquadra Bonds a ogni costo!", "." },
  ["67e2b6848e09fca6"] = { "Le energie risultanti potrebbero però collassare, e questo potrebbe causare un flusso di energia che ti darebbe un'emicrania per settimane.", "." },
  ["67e4d24032fd9bb3"] = { "%s uggiola docilmente.", "." },
  ["67e64c6c38d6436f"] = { "Dopo la caduta di Dalaran, mi congedai dal Kirin Tor. Per anni vegliai su Atiesh, solo per vedermi strappare in un colpo solo il mio ruolo nel Kirin Tor. Avrei ritrovato il bastone, anche a costo di impiegarci una vita intera. È così che entrai nell'⟦Argent Dawn=Alba d'Argento⟧, ed è per questo che ora sono qui.", "." },
  ["67e8dedce2093e9c"] = { "Hai bisogno di volare da qualche parte? Per quello devi andare a ⟦Undercity=Sepulcra⟧! Prendi la strada verso sud uscendo dal paese, poi vai a sud-ovest fino alle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧. Dal retro delle rovine puoi prendere l'ascensore che scende a ⟦Undercity=Sepulcra⟧ e, una volta lì, chiedi indicazioni più precise a un ⟦Undercity Guardian=Guardiano di Sepulcra⟧.", "." },
  ["67ebee1552630f7a"] = { "Hai tutta la mia attenzione.", "." },
  ["67f7229636061bdd"] = { "Sono un BOT. Ho tantissime informazioni. Per scoprire cosa so, sussurrami", "." },
  ["67f7b2fcc4608e92"] = { "Salute, {class} {race}. Sono il comandante Stronghammer, l'ambasciatore che rappresenta qui l'⟦Alliance=Alleanza⟧. Se hai domande sullo stato delle raccolte dell'⟦Alliance=Alleanza⟧ per lo sforzo bellico di ⟦Ahn'Qiraj=Ahn'qiraj⟧, <ragazzo/ragazza>, non esitare a chiedere.", "." },
})
